CREATE TABLE IF NOT EXISTS device_accounts (id TEXT PRIMARY KEY, device_hash TEXT NOT NULL UNIQUE, nickname TEXT NOT NULL, credits INTEGER NOT NULL DEFAULT 0, channel_reward_claimed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS owned_roles (device_account_id TEXT NOT NULL, role_id TEXT NOT NULL, purchased_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(device_account_id, role_id), FOREIGN KEY(device_account_id) REFERENCES device_accounts(id));
CREATE TABLE IF NOT EXISTS purchase_receipts (id TEXT PRIMARY KEY, device_account_id TEXT NOT NULL, product_id TEXT NOT NULL, receipt_hash TEXT NOT NULL UNIQUE, credits_added INTEGER NOT NULL, verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(device_account_id) REFERENCES device_accounts(id));
CREATE TABLE IF NOT EXISTS credit_ledger (id TEXT PRIMARY KEY, device_account_id TEXT NOT NULL, delta INTEGER NOT NULL, reason TEXT NOT NULL, reference_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(device_account_id) REFERENCES device_accounts(id));